const $=s=>document.querySelector(s),status=$('[data-gallery-status]'),folderForm=$('[data-event-form]'),upload=$('[data-event-upload]');
let admin=false,folders=[],selected=new URLSearchParams(location.search).get('carpeta')||'',busy=false;
const node=(tag,text='',cls='')=>{const el=document.createElement(tag);el.textContent=text;el.className=cls;return el;};
async function api(path,method='GET',body){const response=await fetch('/api/'+path,{method,cache:'no-store',...(body instanceof FormData?{body}:body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||'No se pudo completar la operación.'),{status:response.status});return data;}
function capacity(){const folder=folders.find(f=>f.id===upload.elements.folderId.value);$('[data-gallery-capacity]').textContent=folder?folder.photos+' / 100 archivos · '+Math.max(0,100-folder.photos)+' plazas disponibles.':'Selecciona un álbum.';upload.querySelector('button').disabled=busy||!folder||folder.photos>=100;}
upload.elements.folderId.addEventListener('change',capacity);
function resetFolder(){folderForm.reset();folderForm.elements.id.value='';$('[data-event-cancel]').hidden=true;}
function editFolder(folder){folderForm.elements.id.value=folder.id;folderForm.elements.name.value=folder.name;folderForm.elements.category.value=folder.category;folderForm.elements.date.value=folder.event_date;$('[data-event-cancel]').hidden=false;folderForm.scrollIntoView({behavior:'instant'});folderForm.elements.name.focus();}
function viewPhoto(photo){const dialog=$('[data-event-lightbox]'),image=dialog.querySelector('img'),video=dialog.querySelector('video'),isVideo=photo.content_type?.startsWith('video/');image.hidden=!!isVideo;video.hidden=!isVideo;if(isVideo){image.removeAttribute('src');video.src=photo.url;}else{video.removeAttribute('src');image.src=photo.url;image.alt=photo.caption||'Foto del evento';}dialog.querySelector('p').textContent=photo.caption;dialog.showModal();if(!isVideo)window.clubAnalytics?.track('gallery_image_view',{section:'galeria',resource_id:photo.id,album_id:selected});}
$('[data-event-close]').onclick=()=>$('[data-event-lightbox]').close();$('[data-event-lightbox]').addEventListener('close',()=>{const v=$('[data-event-lightbox] video');v.pause();v.removeAttribute('src');v.load();});$('[data-event-lightbox]').onclick=event=>{if(event.target===event.currentTarget)event.currentTarget.close();};
async function openFolder(id){selected=id;const folder=folders.find(f=>f.id===id);if(!folder){$('[data-event-content]').hidden=true;return;}history.replaceState(null,'','galeria.html?carpeta='+encodeURIComponent(id));$('[data-event-content]').hidden=false;$('[data-event-title]').textContent=folder.name;upload.elements.folderId.value=id;capacity();
 const photos=await api('gallery/photos?folder='+encodeURIComponent(id)),grid=$('[data-event-photos]');grid.replaceChildren();window.clubAnalytics?.track('gallery_album_view',{section:'galeria',album_id:id});
 for(const photo of photos){const card=node('article','','event-photo'),button=node('button'),image=node(photo.content_type?.startsWith('video/')?'video':'img');if(image.tagName==='VIDEO'){image.preload='none';image.poster='assets/galeria-emblema-lluvia.jpg';image.muted=true;image.playsInline=true;button.dataset.video='true';}button.type='button';button.setAttribute('aria-label',photo.caption||'Abrir archivo de '+folder.name);image.src=photo.url;image.alt=photo.caption||folder.name;image.loading='lazy';button.append(image);button.onclick=()=>viewPhoto(photo);card.append(button);if(photo.content_type?.startsWith('video/'))button.append(node('span','▶ Vídeo','event-video-label'));if(photo.caption)card.append(node('p',photo.caption));
  if(admin){const remove=node('button','Eliminar archivo','event-remove');remove.type='button';remove.onclick=async()=>{if(!confirm('¿Eliminar definitivamente este archivo?'))return;remove.disabled=true;try{await api('gallery/photos/'+photo.id,'DELETE');await loadFolders();status.textContent='Archivo eliminado.';}catch(error){status.textContent=error.message;remove.disabled=false;}};card.append(remove);}grid.append(card);
 }
 status.textContent=photos.length?photos.length+' fotos y vídeos en '+folder.name+'.':'Esta carpeta todavía no tiene archivos.';
}
function renderFolders(){const category=$('[data-event-filter]').value,grid=$('[data-event-folders]');grid.replaceChildren();for(const folder of folders.filter(f=>!category||f.category===category)){
 const tile=node('article','','garage-folder'),button=node('button');button.type='button';if(folder.cover){const image=node('img');image.src=folder.cover;image.alt='';image.loading='lazy';button.append(image);}else button.append(node('span','▧','garage-folder-symbol'));
 button.append(node('strong',folder.name),node('span',folder.category+(folder.event_date?' · '+folder.event_date.split('-').reverse().join('/'):'')+' · '+folder.photos+' archivos →'));button.onclick=async()=>{try{await openFolder(folder.id);$('[data-event-content]').scrollIntoView({behavior:'instant'});}catch(error){status.textContent=error.message;}};tile.append(button);
 if(admin){const actions=node('div','','garage-folder-tools'),edit=node('button','Editar carpeta'),remove=node('button','Eliminar carpeta');edit.type=remove.type='button';edit.onclick=()=>editFolder(folder);remove.disabled=folder.photos>0;remove.title=folder.photos?'Elimina primero sus archivos.':'Eliminar carpeta vacía';remove.onclick=async()=>{if(!confirm('¿Eliminar la carpeta vacía «'+folder.name+'»?'))return;try{await api('gallery/folders/'+folder.id,'DELETE');if(selected===folder.id)selected='';await loadFolders();}catch(error){status.textContent=error.message;}};actions.append(edit,remove);tile.append(actions);}grid.append(tile);
 }if(!grid.children.length)grid.append(node('p','Todavía no hay carpetas en esta temática.'));
}
async function loadFolders(){folders=await api('gallery/folders');const old=upload.elements.folderId.value;upload.elements.folderId.replaceChildren();for(const folder of folders){const option=node('option',folder.name);option.value=folder.id;upload.elements.folderId.append(option);}if(folders.some(f=>f.id===old))upload.elements.folderId.value=old;upload.querySelector('button').disabled=!folders.length;renderFolders();status.textContent=folders.length?'Elige un evento para ver sus fotos.':admin?'Crea tu primera carpeta en Gestión de la galería.':'El club está preparando los álbumes de sus eventos.';if(selected)await openFolder(selected);else $('[data-event-content]').hidden=true;capacity();}
$('[data-event-filter]').onchange=renderFolders;$('[data-event-back]').onclick=()=>{selected='';history.replaceState(null,'','galeria.html');$('[data-event-content]').hidden=true;$('[data-event-folders]').scrollIntoView({behavior:'instant'});};$('[data-event-cancel]').onclick=resetFolder;
folderForm.onsubmit=async event=>{event.preventDefault();const button=folderForm.querySelector('button[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(folderForm)),folder=await api('gallery/folders'+(data.id?'/'+data.id:''),'POST',data);selected=folder.id;resetFolder();await loadFolders();$('[data-gallery-save]').textContent='Carpeta guardada. Ya puedes subir fotos y vídeos.';}catch(error){$('[data-gallery-save]').textContent=error.message;}finally{button.disabled=false;}};
async function compress(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw new Error('Utiliza fotos JPG, PNG o WebP de menos de 20 MB.');const image=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*ratio));canvas.height=Math.max(1,Math.round(image.height*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();for(const quality of [.85,.7,.5,.3]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=1048576)return blob;}throw new Error('La foto ocupa demasiado.');}
upload.onsubmit=async event=>{event.preventDefault();if(busy)return;const files=[...upload.elements.photos.files];const folderInfo=folders.find(f=>f.id===upload.elements.folderId.value),remaining=Math.max(0,100-(folderInfo?.photos||0));if(!files.length||files.length>100){$('[data-gallery-upload-status]').textContent='Selecciona entre 1 y 100 archivos.';return;}if(files.length>remaining){$('[data-gallery-upload-status]').textContent='En este álbum caben '+remaining+' archivos más. Selecciona esa cantidad o elimina algunas antes.';return;}busy=true;const button=upload.querySelector('button');button.disabled=true;let saved=0;const failed=[];const folder=upload.elements.folderId.value,caption=upload.elements.caption.value,consent=upload.elements.consent.checked?'yes':'no';
 try{for(const [index,file] of files.entries()){$('[data-gallery-upload-status]').textContent='Subiendo foto '+(saved+failed.length+1)+' de '+files.length+'…';try{const data=new FormData();data.set('folderId',folder);data.set('caption',caption);data.set('consent',consent);const video=file.type.startsWith('video/');if(video&&!['video/mp4','video/webm'].includes(file.type))throw Error('Utiliza vídeo MP4 o WebM.');if(video&&file.size>25*1024*1024)throw Error('El vídeo supera 25 MB.');data.set('photo',video?file:await compress(file),video?file.name:'evento.jpg');await api('gallery/photos','POST',data);saved++;}catch(error){failed.push(file.name+': '+error.message);if(error.status===409&&error.message.includes('100')){failed.push(...files.slice(index+1).map(f=>f.name+': álbum completo'));break;}}}selected=folder;await loadFolders();upload.reset();upload.elements.folderId.value=folder;$('[data-gallery-upload-status]').textContent=saved+(files.some(f=>f.type.startsWith('video/'))?' archivos publicados.':' fotos publicadas.')+(failed.length?' No se pudieron subir: '+failed.join('; ')+'. Selecciona de nuevo solo estas fotos.':'');}catch(error){$('[data-gallery-upload-status]').textContent=saved+' fotos publicadas. '+error.message;}finally{busy=false;capacity();}};
try{admin=!!(await api('admin/session')).id;}catch{}$('[data-gallery-management]').hidden=!admin;$('[data-gallery-login]').href=admin?'#gestion':'admin.html?volver=galeria';$('[data-gallery-login]').textContent=admin?'Gestionar carpetas y fotos':'Entrar para gestionar la galería';try{await loadFolders();}catch(error){status.textContent=error.message;}
